const r=await tools.exec_command({cmd:"python - <<'PY'
import json,glob
for fn in glob.glob('*measure.ipynb')+glob.glob('*ana.ipynb'):
 d=json.load(open(fn));print(fn,d['metadata'].get('hera'))
PY",max_output_tokens:1000});text(r.output);
